import {supabase,currentUser,login,saveSettings,loadSettings} from './auth-client.mjs';
import {DOJO_ELEMENTS,emptyDojoLevels} from './account-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./tatari-data/',import.meta.url),el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;return n};
let data,levels=emptyDojoLevels(),actor=null,revision=0,loading=true;
function badgePickers(){const holder=$('account-dojos');holder.replaceChildren();holder.className='account-dojo-elements';for(const [element,label] of DOJO_ELEMENTS){const group=el('div'),button=el('button'),icon=el('img');button.type='button';button.className='account-dojo-element';button.setAttribute('aria-label',label+' Dojo Badges');button.setAttribute('aria-pressed',String(levels[element]>0));icon.src=new URL(data.units.find(u=>u.element===Number(element)).elementImage,root);icon.alt=label;button.append(icon,el('span','Level '+levels[element]));
 const dialog=el('dialog');dialog.className='account-badge-dialog';dialog.setAttribute('aria-label',label+' Dojo Badges');const header=el('div'),close=el('button'),cross=el('img');header.className='badge-dialog-heading';close.className='dialog-close';close.type='button';close.setAttribute('aria-label','Close');cross.src=new URL('images/close-x.png',root);cross.alt='';close.append(cross);close.onclick=()=>dialog.close();header.append(el('h2',label+' Dojo Badges'),close);const row=el('div');row.className='account-badge-options';for(const [i,b] of data.badges.filter(b=>b.element===Number(element)).sort((a,b)=>a.id-b.id).entries()){const choice=el('button'),picture=el('img');choice.type='button';choice.setAttribute('aria-label',label+' badge '+(i+1)+' of 7');choice.setAttribute('aria-pressed',String(i<levels[element]));picture.src=new URL(b.image,root);picture.alt=b.name;choice.append(picture,el('span',(i+1)+' / 7'));choice.onclick=()=>{levels[element]=levels[element]===i+1?0:i+1;dialog.close();badgePickers();$('save-status').textContent='Unsaved changes';};row.append(choice);}dialog.append(header,row);button.onclick=()=>{if(!loading)dialog.showModal()};group.append(button,dialog);holder.append(group);}}

async function refresh(){if(!data)return;const token=++revision;loading=true;actor=null;$('save-dojos').disabled=true;for(const d of document.querySelectorAll('dialog'))d.close();$('account-dojos').replaceChildren();try{const user=await currentUser();if(token!==revision)return;$('signed-out').hidden=!!user;$('signed-in').hidden=!user;if(!user)return;actor=user.id;$('account-status').textContent='Loading your badges…';const saved=await loadSettings();if(token!==revision)return;levels=saved;badgePickers();loading=false;$('save-dojos').disabled=false;$('account-status').textContent='';}catch(e){if(token===revision)$('account-status').textContent='Could not load badges. '+e.message;}}
$('discord-login').onclick=async()=>{try{await login('discord')}catch(e){$('login-status').textContent=e.message}};
$('save-dojos').onclick=async()=>{if(loading||!actor)return;const token=revision,id=actor;loading=true;$('save-dojos').disabled=true;try{const user=await currentUser();if(token!==revision||user?.id!==id)return;await saveSettings(levels);if(token===revision)$('save-status').textContent='Dojo settings saved.';}catch(e){if(token===revision)$('save-status').textContent=e.message;}finally{if(token===revision){loading=false;$('save-dojos').disabled=false}}};
supabase.auth.onAuthStateChange(event=>{if(event!=='TOKEN_REFRESHED')setTimeout(refresh,0)});
try{const response=await fetch(new URL('roster.json',root));if(!response.ok)throw Error('Badge assets unavailable.');data=await response.json();await refresh()}catch(e){$('account-status').textContent=e.message}
